// BatchNormalizationForwardTraining Execute forward training layer for batch normalization
//
// Batch normalization pass for forward training pass.
// Takes in batch normalization mode bn_mode and input tensor x, output tensor y, bnBias and bnScale
// with their descriptor.
//
// If either resultSaveMean, or resultSaveInvVariance are null pointers then the values for the mean
// and inverse variance will not be used.
//
// Likewise, if either resultRunningMean, or resultRunningVariance are null pointers then the values
// for the running mean and variance will not be saved.
// Running averages and variances are scaled using an exponential averaging factor: \f[
// \mu_{old} = \mu_{new}*factor + \mu_{old}*(1-factor)
// \f]
// where \f[
// factor=1/(1+iteration)
// \f]
//
//   - handle: MIOpen handle (input)
//   - bnMode: Batch normalization mode (input)
//   - alpha: Floating point scaling factor, allocated on the host (input)
//   - beta: Floating point shift factor, allocated on the host (input)
//   - xDesc: Tensor descriptor for data input tensor x (input)
//   - x: Data tensor x (input)
//   - yDesc: Tensor descriptor for output data tensor y (input)
//   - y: Data tensor y (output)
//   - bnScaleBiasMeanVarDesc: Tensor descriptor for BN scaling, shifting, saved variance and mean (input)
//   - bnScale: Batch norm scaling, gamma, tensor (input)
//   - bnBias: Batch norm bias, beta, tensor (input)
//   - expAvgFactor: Exponential averaging factor (input)
//   - resultRunningMean: Running average saved for inference (output)
//   - resultRunningVariance: Running variance saved for inference (output)
//   - epsilon: Value to stablize inverse variance calculation (input)
//   - resultSaveMean: Saved mini-batch mean for backwards pass (output)
//   - resultSaveInvVariance: Saved mini-batch inverse variance for backwards pass (output)
//
// Wraps miopenBatchNormalizationForwardTraining.
func BatchNormalizationForwardTraining(handle Handle, bnMode BatchNormMode, alpha uintptr, beta uintptr, xDesc TensorDescriptor, x uintptr, yDesc TensorDescriptor, y uintptr, bnScaleBiasMeanVarDesc TensorDescriptor, bnScale uintptr, bnBias uintptr, expAvgFactor float64, resultRunningMean uintptr, resultRunningVariance uintptr, epsilon float64, resultSaveMean uintptr, resultSaveInvVariance uintptr) error {
	if err := checkLib(); err != nil {
		return err
	}
	return toError(fnBatchNormalizationForwardTraining(handle, bnMode, alpha, beta, xDesc, x, yDesc, y, bnScaleBiasMeanVarDesc, bnScale, bnBias, expAvgFactor, resultRunningMean, resultRunningVariance, epsilon, resultSaveMean, resultSaveInvVariance))
}

