// FusedAdam Perform Fused Adam optimization for a single tensor (Adaptive Moment Estimation).
//
// This function implements the Fused Adam optimization algorithm. Adam, short for Adaptive Moment
// Estimation, extends the RMSProp optimizer. It combines the advantages of AdaGrad and RMSProp by
// adaptively adjusting learning rates for each parameter using the first and second moments of
// gradients. Fused Adam optimization efficiently combines multiple operations into a single kernel,
// reducing memory access overhead and improving performance.
//
// Additionally, Fused Adam can be utilized in both adam w and Automatic Mixed Precision (AMP),
// enabling accelerated model training and reduced memory consumption. AMP supports FP16
// computation, optimizing model calculations using a mixture of FP32 and FP16 precision to enhance
// training speed. When utilizing AMP, FoundInf, ScaleGrad, and step tensors should be employed. In
// AMP mode, the execution of Adam is determined based on the FoundInf value. State Step accepts
// both int values and int tensors. If a Step tensor is employed, the step received as an int is
// disregarded, and if Adam is executed, the step tensor is incremented by 1.
//
// @code
// // Execute Adam
// [Handle.FusedAdam](handle,
// paramDesc,
// param,
// gradDesc,
// grad,
// expAvgDesc,
// expAvg,
// expAvgSqDesc,
// expAvgSq,
// NULL, // Unused maxExpAvgSqDesc because amsgrad is false
// NULL,
// NULL, // Unused stateStep Tensor because use step integer argument
// NULL,
// step,
// lr,
// beta1,
// beta2,
// weight_decay,
// eps,
// false, // amsgrad
// false, // maximize
// false, // adamw
// NULL, // Unused gradScale Tensor because not amp
// NULL,
// NULL, // Unused foundInf Tensor because not amp
// NULL);
//
// // Execute AdamW
// [Handle.FusedAdam](handle,
// paramDesc,
// param,
// gradDesc,
// grad,
// expAvgDesc,
// expAvg,
// expAvgSqDesc,
// expAvgSq,
// NULL, // Unused maxExpAvgSqDesc because amsgrad is false
// NULL,
// NULL, // Unused stateStep Tensor because use step integer argument
// NULL,
// step,
// lr,
// beta1,
// beta2,
// weight_decay,
// eps,
// false, // amsgrad
// false, // maximize
// true, // adamw
// NULL, // Unused gradScale Tensor because not amp
// NULL,
// NULL, // Unused foundInf Tensor because not amp
// NULL);
//
// // Execute AMP Adam
// [Handle.FusedAdam](handle,
// paramDesc,
// param,
// gradDesc,
// grad,
// expAvgDesc,
// expAvg,
// expAvgSqDesc,
// expAvgSq,
// NULL, // Unused maxExpAvgSqDesc because amsgrad is false
// NULL,
// stateStepDesc,
// stateStep,
// -1, // Ignore step value because stateStep Tensor is used
// lr,
// beta1,
// beta2,
// weight_decay,
// eps,
// false, // amsgrad
// false, // maximize
// false, // adamw
// gradScaleDesc,
// gradScale,
// foundInfDesc,
// foundInf);
// @endcode
//
//   - handle: MIOpen handle (input)
//   - paramDesc: Tensor descriptor for the input parameter tensor (input)
//   - param: Input parameter tensor (input)
//   - gradDesc: Tensor descriptor for the input gradient tensor (input)
//   - grad: Input gradient tensor (input)
//   - expAvgDesc: Tensor descriptor for the input exponential moving average tensor (input)
//   - expAvg: Input exponential moving average tensor (input)
//   - expAvgSqDesc: Tensor descriptor for the input exponential moving average squared tensor (input)
//   - expAvgSq: Input exponential moving average squared tensor (input)
//   - maxExpAvgSqDesc: Tensor descriptor for the input maximum exponential moving average squared tensor. Used when amsgrad is true (input, optional)
//   - maxExpAvgSq: Input maximum exponential moving average squared tensor. Used when amsgrad is true (input, optional)
//   - stateStepDesc: Tensor descriptor for the input state step tensor (input)
//   - stateStep: Input state step tensor (input)
//   - stateStep: Input state step. used when the step tensor is null (input)
//   - lr: Learning rate (input)
//   - beta1: Coefficient used for computing the first moment running average of gradient (input)
//   - beta2: Coefficient used for computing the second moment running average of gradient (input)
//   - weightDecay: Weight decay (input)
//   - eps: Term added to the denominator to improve numerical stability (input)
//   - amsgrad: Flag indicating whether to use the AMSGrad variant of Adam (input)
//   - maximize: Flag indicating whether to maximize the objective with respect to the parameters (input)
//   - adamw: If true, the operation becomes AdamW (input)
//   - gradScaleDesc: Tensor descriptor for the input grad scale tensor (input, optional)
//   - gradScale: Input grad scale tensor (input, optional)
//   - foundInfDesc: Tensor descriptor for the input found inf tensor (input, optional)
//   - foundInf: Tensor indicating the presence of inf or NaN in gradients. If true, skips operation and step update (input, optional)
//
// Wraps miopenFusedAdam.
func FusedAdam(handle Handle, paramDesc TensorDescriptor, param uintptr, gradDesc TensorDescriptor, grad uintptr, expAvgDesc TensorDescriptor, expAvg uintptr, expAvgSqDesc TensorDescriptor, expAvgSq uintptr, maxExpAvgSqDesc TensorDescriptor, maxExpAvgSq uintptr, stateStepDesc TensorDescriptor, stateStep uintptr, stateStep2 uint32, lr float32, beta1 float32, beta2 float32, weightDecay float32, eps float32, amsgrad bool, maximize bool, adamw bool, gradScaleDesc TensorDescriptor, gradScale uintptr, foundInfDesc TensorDescriptor, foundInf uintptr) error {
	if err := checkLib(); err != nil {
		return err
	}
	return toError(fnFusedAdam(handle, paramDesc, param, gradDesc, grad, expAvgDesc, expAvg, expAvgSqDesc, expAvgSq, maxExpAvgSqDesc, maxExpAvgSq, stateStepDesc, stateStep, stateStep2, lr, beta1, beta2, weightDecay, eps, amsgrad, maximize, adamw, gradScaleDesc, gradScale, foundInfDesc, foundInf))
}

